curl -s -X POST http://localhost:4000/api/blogs \
  -H "Authorization: Bearer $AUTH_TOKEN" \
  -H "Content-Type: multipart/form-data" \
  -F "data={\"slug\":\"home-loan-guide-nepal-2026\",\"title\":\"Home Loan Guide Nepal 2026: Interest Rates, Eligibility, and Tips\",\"category\":\"Finance\",\"excerpt\":\"Everything you need to know about getting a home loan in Nepal. Compare interest rates from major banks, understand eligibility criteria, and learn tips to get the best deal.\",\"content\":\"Home loans in Nepal have become more accessible in 2026. Major banks offer interest rates between 8-12 percent depending on your credit profile. NRB guidelines allow banks to lend up to 70 percent of property value. Eligibility requirements include: stable income for at least 2 years, good credit history, age between 21-60 years, and Nepali citizenship. Required documents: citizenship certificate, income proof, bank statements, property documents, and valuation report. Tips for better rates: maintain a good credit score, compare offers from multiple banks, consider joint applications, and negotiate processing fees. Processing fees typically range from 0.5-1 percent of the loan amount. Most banks offer repayment periods of 15-25 years.\",\"author\":\"Bikash Rai\",\"authorRole\":\"Marketing Director\",\"readTime\":\"11 min read\",\"isFeatured\":true}"
